BEGIN;
CREATE OR REPLACE FUNCTION encova_finance_rollforward_report(report_kind TEXT,date_from DATE,cutoff DATE,search TEXT,requested_page INTEGER,issue_page INTEGER) RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE result JSONB;BEGIN
 WITH events AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_events(report_kind,cutoff)),groups AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_groups(report_kind,cutoff)),
 positions AS MATERIALIZED(SELECT "entityId",metric,coalesce(sum(delta) FILTER(WHERE "effectiveDate"<date_from),0) AS opening,coalesce(sum(delta) FILTER(WHERE "effectiveDate">=date_from AND delta>0),0) AS increases,-coalesce(sum(delta) FILTER(WHERE "effectiveDate">=date_from AND delta<0),0) AS decreases,sum(delta) AS closing,count(*) FILTER(WHERE "effectiveDate">=date_from)::integer AS period_events FROM events GROUP BY "entityId",metric),
 full_rows AS MATERIALIZED(SELECT g.*,v.opening,v.increases,v.decreases,v.increases-v.decreases AS net,v.closing,v.period_events FROM groups g JOIN positions v ON v."entityId" IS NOT DISTINCT FROM g."entityId" AND v.metric=g.metric),
 controls AS MATERIALIZED(SELECT * FROM public.encova_finance_rollforward_controls(report_kind,date_from,cutoff)),books AS(SELECT coalesce(sum(l.debit-l.credit) FILTER(WHERE e."postingDate"<date_from),0) AS opening,coalesce(sum(l.debit-l.credit),0) AS closing FROM public."FinanceJournalLine" l JOIN public."FinanceJournalEntry" e ON e.id=l."journalId" WHERE e."postingDate"<=cutoff),
 diagnostics AS MATERIALIZED(SELECT 'ACCOUNT:'||"accountId"::text AS "issueKey",'ACCOUNT'::text AS scope,code||' · '||name AS label,"accountId",NULL::text AS "rowKey",NULL::text AS metric,"openingSubledger","openingControl","openingDifference","closingSubledger","closingControl","closingDifference" FROM controls WHERE "openingDifference"<>0 OR "closingDifference"<>0
 UNION ALL SELECT 'ROW:'||"rowKey",'NEGATIVE_ROW',coalesce(number||' · ','')||name,NULL::uuid,"rowKey",metric,opening,NULL::numeric,NULL::numeric,closing,NULL::numeric,closing FROM full_rows WHERE report_kind<>'PROJECTS' AND closing<0
 UNION ALL SELECT 'BOOK','BOOK','Company journal balance',NULL::uuid,NULL::text,NULL::text,NULL::numeric,NULL::numeric,opening,NULL::numeric,NULL::numeric,closing FROM books WHERE opening<>0 OR closing<>0),
 issue_counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM diagnostics),ip AS(SELECT *,least(issue_page,pages) AS page FROM issue_counts),bounded_issues AS(SELECT * FROM diagnostics ORDER BY scope,label,"issueKey" LIMIT 25 OFFSET((SELECT page FROM ip)-1)*25),issue_rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('issueKey',"issueKey",'scope',scope,'label',label,'accountId',"accountId",'rowKey',"rowKey",'metric',metric,'openingSubledger',CASE WHEN "openingSubledger" IS NOT NULL THEN round("openingSubledger",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END,'openingControl',CASE WHEN "openingControl" IS NOT NULL THEN round("openingControl",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END,'openingDifference',CASE WHEN "openingDifference" IS NOT NULL THEN round("openingDifference",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END,'closingSubledger',CASE WHEN "closingSubledger" IS NOT NULL THEN round("closingSubledger",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END,'closingControl',CASE WHEN "closingControl" IS NOT NULL THEN round("closingControl",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END,'closingDifference',CASE WHEN "closingDifference" IS NOT NULL THEN round("closingDifference",CASE WHEN metric='UNITS' THEN 6 ELSE 2 END)::text END) ORDER BY scope,label,"issueKey"),'[]'::jsonb) AS items FROM bounded_issues),
 totals AS(SELECT coalesce(jsonb_agg(jsonb_build_object('metric',metric,'unit','PKR','openingBalance',round(opening,2)::text,'increases',round(increases,2)::text,'decreases',round(decreases,2)::text,'periodNet',round(increases-decreases,2)::text,'closingBalance',round(closing,2)::text) ORDER BY metric),'[]'::jsonb) AS items FROM(SELECT metric,sum(opening) AS opening,sum(increases) AS increases,sum(decreases) AS decreases,sum(closing) AS closing FROM full_rows WHERE metric<>'UNITS' GROUP BY metric)b),
 displayed AS MATERIALIZED(SELECT * FROM full_rows WHERE(opening<>0 OR period_events>0 OR closing<>0) AND concat_ws(' ',name,number,metric,"entityId") ILIKE '%'||search||'%'),counts AS(SELECT count(*)::integer AS total,greatest(1,ceil(count(*)/25.0)::integer) AS pages FROM displayed),paging AS(SELECT *,least(requested_page,pages) AS page FROM counts),bounded AS(SELECT * FROM displayed ORDER BY name,number NULLS FIRST,"entityId" NULLS FIRST,metric LIMIT 25 OFFSET((SELECT page FROM paging)-1)*25),rows AS(SELECT coalesce(jsonb_agg(jsonb_build_object('rowKey',"rowKey",'entityId',"entityId",'name',name,'number',number,'active',active,'entityHref',"entityHref",'metric',metric,'unit',unit,'eventCount',"eventCount",'accountCount',"accountCount",'periodEventCount',period_events,'openingBalance',round(opening,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'increases',round(increases,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'decreases',round(decreases,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'periodNet',round(net,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text,'closingBalance',round(closing,CASE WHEN unit='UNITS' THEN 6 ELSE 2 END)::text) ORDER BY name,number NULLS FIRST,"entityId" NULLS FIRST,metric),'[]'::jsonb) AS items FROM bounded),
 proof AS(SELECT encode(sha256(convert_to(coalesce(jsonb_agg(jsonb_build_object('key',"eventKey",'entity',"entityId",'account',"accountId",'metric',metric,'date',"effectiveDate",'delta',delta::text,'journalId',"journalId",'sourceType',"sourceType",'sourceId',"sourceId") ORDER BY "eventKey"),'[]'::jsonb)::text,'UTF8')),'hex') AS digest FROM events)
 SELECT jsonb_build_object('metadata',public.encova_finance_report_metadata(date_from,cutoff,jsonb_build_object('report','ROLL_FORWARD','kind',report_kind,'displaySearch',search,'eventDigest',proof.digest,'registerBasis',CASE WHEN report_kind='ASSETS' THEN 'Current retained register allocation of actual historical purchase cost; unassigned GL cost remains an explicit control issue' ELSE 'Actual posted dated events' END)),'kind',report_kind,'totals',totals.items,'reconciliation',jsonb_build_object('ready',ip.total=0,'issueCount',ip.total,'controlCount',(SELECT count(*) FROM controls),'negativeRowCount',(SELECT count(*) FROM diagnostics WHERE scope='NEGATIVE_ROW'),'openingBookDifference',round(books.opening,2)::text,'closingBookDifference',round(books.closing,2)::text,'issues',issue_rows.items,'page',ip.page,'pages',ip.pages),'items',rows.items,'total',paging.total,'page',paging.page,'pages',paging.pages) INTO result FROM paging CROSS JOIN rows CROSS JOIN totals CROSS JOIN ip CROSS JOIN issue_rows CROSS JOIN proof CROSS JOIN books;RETURN result;
END $$;
COMMIT;
